            updated_at         DATETIME,
            KEY idx_sr_status (status),
            KEY idx_sr_customer (customer_id),
            UNIQUE KEY uq_sr_number (doc_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

