            created_at           DATETIME,
            updated_at           DATETIME,
            KEY idx_est_sr (service_request_id),
            KEY idx_est_status (status),
            UNIQUE KEY uq_est_number (doc_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

