CREATE TABLE IF NOT EXISTS square_transactions (
            id               INT AUTO_INCREMENT PRIMARY KEY,
            square_id        VARCHAR(191) NOT NULL,
            object_type      VARCHAR(16) NOT NULL DEFAULT 'PAYMENT',
            location_id      VARCHAR(64),
            order_id         VARCHAR(64),
            status           VARCHAR(24),
            amount           DECIMAL(12,2) NOT NULL DEFAULT 0,
            tip_amount       DECIMAL(12,2) NOT NULL DEFAULT 0,
            fee_amount       DECIMAL(12,2) NOT NULL DEFAULT 0,
            net_amount       DECIMAL(12,2) NOT NULL DEFAULT 0,
            refunded_amount  DECIMAL(12,2) NOT NULL DEFAULT 0,
            currency         VARCHAR(8) NOT NULL DEFAULT 'USD',
            source_type      VARCHAR(24),
            card_brand       VARCHAR(24),
            card_last4       VARCHAR(8),
            entry_method     VARCHAR(24),
            customer_name    VARCHAR(160),
            note             VARCHAR(255),
            reference_id     VARCHAR(120),
            receipt_url      VARCHAR(512),
            occurred_at      DATETIME,
            square_customer_id VARCHAR(64),
            cardholder_name  VARCHAR(160),
            buyer_email      VARCHAR(160),
            /* IDENTIFYING DETAIL.
             *
             * Six years of charges with no documents behind them are told
             * apart by circumstance, not by amount: which device rang it up,
             * which Square app, what the customer saw on their statement, what
             * the receipt number was. All of it was already arriving in the
             * payload and being dropped on the floor — the first mapping kept
             * eight fields out of sixty.
             *
             * card_fingerprint is the quiet one worth having: Square hashes
             * the physical card, so it groups every charge from the same card
             * across six years even when the name was never captured. */
            receipt_number   VARCHAR(32),
            device_name      VARCHAR(120),
            square_product   VARCHAR(32),
            statement_desc   VARCHAR(80),
            card_fingerprint VARCHAR(96),
            card_exp         VARCHAR(8),
            card_type        VARCHAR(16),
            card_bin         VARCHAR(8),
            avs_status       VARCHAR(16),
            cvv_status       VARCHAR(16),
            decline_code     VARCHAR(48),
            decline_detail   VARCHAR(255),
            team_member_id   VARCHAR(64),
            classification   VARCHAR(16) NOT NULL DEFAULT 'UNREVIEWED',
            classified_by    INTEGER,
            classified_at    DATETIME,
            invoice_id       INTEGER,
            payment_id       INTEGER,
            posted_entry_id  INTEGER,
            raw              TEXT,
            first_seen_at    DATETIME,
            last_synced_at   DATETIME,
            UNIQUE KEY uq_sq_id (square_id),
            KEY idx_sq_class (classification),
            KEY idx_sq_order (order_id),
            KEY idx_sq_when (occurred_at),
            KEY idx_sq_cust (square_customer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS square_customers (
            id                   INT AUTO_INCREMENT PRIMARY KEY,
            square_customer_id   VARCHAR(64) NOT NULL,
            given_name           VARCHAR(80),
            family_name          VARCHAR(80),
            company_name         VARCHAR(160),
            phone_number         VARCHAR(32),
            phone_e164           VARCHAR(16),
            email_address        VARCHAR(160),
            address_line1        VARCHAR(160),
            city                 VARCHAR(80),
            state                VARCHAR(8),
            postal_code          VARCHAR(12),
            note                 VARCHAR(255),
            reference_id         VARCHAR(120),
            created_at_square    DATETIME,
            payment_count        INTEGER NOT NULL DEFAULT 0,
            payment_total        DECIMAL(12,2) NOT NULL DEFAULT 0,
            first_seen_job       DATETIME,
            last_seen_job        DATETIME,
            promoted_customer_id INTEGER,
            promoted_at          DATETIME,
            raw                  TEXT,
            first_seen_at        DATETIME,
            last_synced_at       DATETIME,
            UNIQUE KEY uq_sqc_id (square_customer_id),
            KEY idx_sqc_phone (phone_e164),
            KEY idx_sqc_promoted (promoted_customer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS square_loans (
            id             INT AUTO_INCREMENT PRIMARY KEY,
            plan_id        VARCHAR(48) NOT NULL,
            loan_amount    DECIMAL(12,2) NOT NULL DEFAULT 0,
            loan_fee       DECIMAL(12,2) NOT NULL DEFAULT 0,
            total_owed     DECIMAL(12,2) NOT NULL DEFAULT 0,
            total_paid     DECIMAL(12,2) NOT NULL DEFAULT 0,
            balance        DECIMAL(12,2) NOT NULL DEFAULT 0,
            repay_pct      DECIMAL(6,2),
            status         VARCHAR(16) NOT NULL DEFAULT 'PAID',
            paid_off_on    VARCHAR(10),
            posted_entry_id INTEGER,
            notes          TEXT,
            created_at     DATETIME,
            updated_at     DATETIME,
            UNIQUE KEY uq_sql_plan (plan_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS square_payout_entries (
            id                INT AUTO_INCREMENT PRIMARY KEY,
            square_entry_id   VARCHAR(191) NOT NULL,
            payout_square_id  VARCHAR(191) NOT NULL,
            payout_row_id     INTEGER,
            entry_type        VARCHAR(48) NOT NULL,
            effective_at      DATETIME,
            gross_amount      DECIMAL(12,2) NOT NULL DEFAULT 0,
            fee_amount        DECIMAL(12,2) NOT NULL DEFAULT 0,
            net_amount        DECIMAL(12,2) NOT NULL DEFAULT 0,
            currency          VARCHAR(8) NOT NULL DEFAULT 'USD',
            related_square_id VARCHAR(191),
            posted_entry_id   INTEGER,
            raw               TEXT,
            first_seen_at     DATETIME,
            last_synced_at    DATETIME,
            UNIQUE KEY uq_sqe_id (square_entry_id),
            KEY idx_sqe_payout (payout_square_id),
            KEY idx_sqe_type (entry_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bank_sources (
            id              INT AUTO_INCREMENT PRIMARY KEY,
            name            VARCHAR(120) NOT NULL,
            institution     VARCHAR(120),
            kind            VARCHAR(16) NOT NULL DEFAULT 'CHECKING',
            account_code    VARCHAR(8) NOT NULL DEFAULT '1010',
            last4           VARCHAR(8),
            is_active       INTEGER NOT NULL DEFAULT 1,
            last_import_at  DATETIME,
            notes           TEXT,
            created_at      DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bank_transactions (
            id               INT AUTO_INCREMENT PRIMARY KEY,
            source_id        INTEGER NOT NULL,
            external_id      VARCHAR(191) NOT NULL,
            posted_on        VARCHAR(10) NOT NULL,
            amount           DECIMAL(12,2) NOT NULL DEFAULT 0,
            direction        VARCHAR(8) NOT NULL DEFAULT 'DEBIT',
            raw_descriptor   VARCHAR(255) NOT NULL,
            match_key        VARCHAR(255),
            memo             VARCHAR(255),
            check_number     VARCHAR(24),
            /* PROPOSED, not decided. The rule that suggested it and the account
             * it suggested, kept apart from the account a human confirmed, so
             * 'the engine guessed right' and 'a person agreed' are different
             * facts and the hit rate is measurable. */
            suggested_account VARCHAR(8),
            suggested_rule_id INTEGER,
            account_code     VARCHAR(8),
            classification   VARCHAR(16) NOT NULL DEFAULT 'UNREVIEWED',
            reviewed_by_id   INTEGER,
            reviewed_at      DATETIME,
            expense_id       INTEGER,
            posted_entry_id  INTEGER,
            raw              TEXT,
            first_seen_at    DATETIME,
            last_seen_at     DATETIME,
            UNIQUE KEY uq_bank_ext (source_id, external_id),
            KEY idx_bank_date (posted_on),
            KEY idx_bank_class (classification),
            KEY idx_bank_key (match_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS expense_rules (
            id              INT AUTO_INCREMENT PRIMARY KEY,
            pattern         VARCHAR(190) NOT NULL,
            is_regex        INTEGER NOT NULL DEFAULT 0,
            account_code    VARCHAR(8) NOT NULL,
            classification  VARCHAR(16) NOT NULL DEFAULT 'BUSINESS',
            vendor_name     VARCHAR(160),
            priority        INTEGER NOT NULL DEFAULT 100,
            is_active       INTEGER NOT NULL DEFAULT 1,
            hits            INTEGER NOT NULL DEFAULT 0,
            created_by_id   INTEGER,
            source          VARCHAR(16) NOT NULL DEFAULT 'SEED',
            notes           TEXT,
            last_matched_at DATETIME,
            created_at      DATETIME,
            KEY idx_rule_active (is_active, priority)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS square_sync_state (
            object_type   VARCHAR(16) NOT NULL,
            cursor_time   DATETIME,
            last_run_at   DATETIME,
            last_result   VARCHAR(255),
            imported      INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (object_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS journal_entries (
            id                INT AUTO_INCREMENT PRIMARY KEY,
            entry_no          VARCHAR(32) NOT NULL,
            entry_date        VARCHAR(10) NOT NULL,
            period_key        VARCHAR(7)  NOT NULL,
            source_type       VARCHAR(8)  NOT NULL,
            source_id         INTEGER,
            source_ref        VARCHAR(48),
            memo              VARCHAR(255),
            total_cents       INTEGER NOT NULL DEFAULT 0,
            is_reversal       INTEGER NOT NULL DEFAULT 0,
            reverses_entry_id INTEGER,
            reversed_by_id    INTEGER,
            posted_by_id      INTEGER,
            posted_by_name    VARCHAR(120),
            posted_at         DATETIME,
            created_at        DATETIME,
            KEY idx_je_source (source_type, source_id),
            KEY idx_je_period (period_key),
            KEY idx_je_date (entry_date),
            UNIQUE KEY uq_je_number (entry_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS journal_lines (
            id             INT AUTO_INCREMENT PRIMARY KEY,
            entry_id       INTEGER NOT NULL,
            line_no        INTEGER NOT NULL DEFAULT 1,
            account_number VARCHAR(8) NOT NULL,
            account_name   VARCHAR(120),
            account_type   VARCHAR(16),
            debit          DECIMAL(12,2) NOT NULL DEFAULT 0,
            credit         DECIMAL(12,2) NOT NULL DEFAULT 0,
            debit_cents    INTEGER NOT NULL DEFAULT 0,
            credit_cents   INTEGER NOT NULL DEFAULT 0,
            memo           VARCHAR(255),
            KEY idx_jl_entry (entry_id),
            KEY idx_jl_account (account_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
